code='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    boxes = []
    # Detect rectangular outlines: a color spanning a filled rectangular perimeter.
    for color in set(v for row in grid for v in row) - {0}:
        coords = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0, r1 = min(r for r, c in coords), max(r for r, c in coords)
        c0, c1 = min(c for r, c in coords), max(c for r, c in coords)
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        perimeter = {(r, c) for r in range(r0, r1+1) for c in range(c0, c1+1)
                     if r in (r0, r1) or c in (c0, c1)}
        if all(grid[r][c] == color for r, c in perimeter):
            boxes.append((color, r0, c0, r1, c1, (r1-r0-1)*(c1-c0-1)))
    # Rank frame sizes and scattered marker colors by their counts.
    frame_order = sorted(boxes, key=lambda b: ((b[5]+1)//2, b[5]))
    box_cells = {(r,c) for _,r0,c0,r1,c1,_ in boxes
                 for r in range(r0,r1+1) for c in range(c0,c1+1)}
    counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                     if grid[r][c] != 0 and (r,c) not in box_cells)
    marker_colors = sorted(counts, key=lambda col: (counts[col], col))
    out = [[0]*w for _ in range(h)]
    for frame, marker in zip(frame_order, marker_colors):
        color,r0,c0,r1,c1,_ = frame
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                if r in (r0,r1) or c in (c0,c1):
                    out[r][c] = color
                elif (r-r0+c-c0)%2 == 0:
                    out[r][c] = marker
    return out
'''
